   341	  const loadEvents = useCallback(async (pageNum = 0, isLoadMore = false) => {
   342	    if (isLoadMore) {
   343	      setLoadingMore(true);
   344	    } else {
   345	      setLoading(true);
   346	    }
   347	    
   348	    try {
   349	      // Try Supabase first, fall back to direct API
   350	      const result = await fetchEventsFromSupabase();
   351	      const data = result.events || [];
   352	      const sources = result.sources || [];
   353	      
   354	      if (isLoadMore) {
   355	        setEvents(prev => [...prev, ...data]);
   356	      } else {
   357	        setEvents(data);
   358	        setAvailableSources(sources);
   359	      }
   360	      setPage(pageNum);
   361	    } catch (err) {
   362	      setError(err.message);
   363	      console.error('Failed to load events:', err);
   364	    } finally {
   365	      setLoading(false);
   366	      setLoadingMore(false);
   367	    }
   368	  }, []);
